package com.phoenix.business.repository; import com.phoenix.business.domain.Member; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import org.springframework.data.domain.*; import java.time.LocalDate; public interface MemberRepository extends JpaRepository<Member,Long>{@Query("select m from Member m where (:q is null or lower(m.name) like lower(concat('%',:q,'%')) or lower(m.memberCode) like lower(concat('%',:q,'%')) or lower(coalesce(m.phone,'')) like lower(concat('%',:q,'%'))) and (:status is null or m.status=:status)") Page<Member> search(@Param("q") String q,@Param("status") Member.Status status,Pageable pageable); long countByStatus(Member.Status s); long countByExpiryDateBetween(LocalDate a,LocalDate b); long countByJoinDateBetween(LocalDate a,LocalDate b); boolean existsByEmailIgnoreCaseAndIdNot(String email,Long id); boolean existsByPhoneAndIdNot(String phone,Long id);}
